def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def safe_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    env = observation.get("environment_name", "") or ""
    sx, sy = safe_pos(observation.get("self_position"))
    ox, oy = safe_pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") or "pursuer"
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = []
        if gw > 0 and gh > 0:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if corners:
            target = None
            best_score = None
            for c in corners:
                score = manhattan(c, opp_pos)
                if best_score is None or score > best_score:
                    best_score = score
                    target = c
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        candidates = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("neutral_cells")
            or []
        )
        best = None
        best_score = None
        for item in candidates:
            p = safe_pos(item, None)
            if p is None:
                continue
            score = manhattan(self_pos, p)
            if best_score is None or score < best_score:
                best_score = score
                best = p
        if best is not None:
            return step_toward(self_pos, best)

        # fallback: pressure opponent or drift toward center
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        if gw > 0 and gh > 0:
            center = (gw // 2, gh // 2)
            if manhattan(self_pos, opp_pos) > 1:
                return step_toward(self_pos, center)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for item in resources:
        p = safe_pos(item, None)
        if p is None:
            continue
        score = manhattan(self_pos, p)
        if best_score is None or score < best_score:
            best_score = score
            best = p
    if best is not None:
        return step_toward(self_pos, best)

    # Generic fallback: either pursue or evade depending on proximity.
    if manhattan(self_pos, opp_pos) <= 2:
        return step_away(self_pos, opp_pos)
    return step_toward(self_pos, opp_pos)

